import React from 'react';

import { svgPlotLayout } from '../../core/components/chart-grid/ChartGridRoot.sty.js';
import { useGridPlotSize } from '../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { GridLine } from '../../core/components/grid/GridLine.js';
import { useVisibleAxes } from '../hooks/useVisibleAxes.js';
import { useXYChartYScale } from '../hooks/useXYChartYScale.js';

export function GridZeroLineX() {
  const { height, width } = useGridPlotSize();
  const yScale = useXYChartYScale();
  const { scales } = useVisibleAxes();
  const xScale = scales.bottom;

  if (xScale === undefined) {
    return undefined;
  }

  const max = xScale.invert(0);
  const min = xScale.invert(width);

  const minPixels = xScale(min);
  const zeroPixels = yScale(0);
  const maxPixels = xScale(max);
  const showLine = zeroPixels < height;

  const from = { x: minPixels, y: zeroPixels };
  const to = { x: maxPixels, y: zeroPixels };

  return showLine ? (
    <svg className={svgPlotLayout}>
      <GridLine from={from} to={to} highlight />
    </svg>
  ) : null;
}

GridZeroLineX['displayName'] = 'GridZeroLineX';
